using Microsoft.Extensions.Logging;

public class OrderService
{
    private const decimal VipDiscountRate = 0.1m;
    private const decimal BulkDiscountThreshold = 1000m;
    private const decimal BulkDiscountAmount = 25m;

    private readonly IOrderRepository _repo;
    private readonly ILogger<OrderService> _log;

    public OrderService(IOrderRepository repo, ILogger<OrderService> log)
    {
        _repo = repo;
        _log = log;
    }

    public decimal Total(int orderId)
    {
        var order = _repo.Get(orderId);
        if (order is null)
        {
            _log.LogWarning("Order not found for ID {OrderId}", orderId);
            return 0m;
        }

        var subtotal = order.Lines
            .Where(line => line.Qty > 0)
            .Sum(line => line.Qty * line.Price);

        if (order.Customer?.IsVip == true)
        {
            subtotal -= subtotal * VipDiscountRate;
        }

        if (subtotal > BulkDiscountThreshold)
        {
            subtotal -= BulkDiscountAmount;
        }

        return subtotal;
    }
}
